Dataspatium.assets.register("presets/api/sgu-geodata.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"sgu-geodata\",\n  \"name\": \"SGU öppna geodata (WFS)\",\n  \"publisher\": \"Sveriges geologiska undersökning\",\n  \"description\": \"Geologiska lager från SGU: jordarter, berggrund, brunnar, grundvatten och mer. Välj lager och hämta objekten med geometri; begränsa gärna med ett område (bbox).\",\n  \"docs\": \"https://www.sgu.se/produkter-och-tjanster/geologiska-data/\",\n  \"license\": {\n    \"name\": \"SGU öppna data\",\n    \"url\": \"https://www.sgu.se/produkter-och-tjanster/geologiska-data/oppna-data/\"\n  },\n  \"level\": 1,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://maps3.sgu.se/geoserver/wfs\",\n  \"auth\": {\n    \"type\": \"none\"\n  },\n  \"family\": {\n    \"type\": \"geodata\",\n    \"kind\": \"wfs\"\n  },\n  \"endpoints\": [],\n  \"notes\": \"Lagren hämtas från tjänsten när källan öppnas (GetCapabilities respektive tjänstekatalogen). Svaren är GeoJSON i WGS 84 och öppnas som kartor.\",\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"SGU open geodata (WFS)\",\n      \"description\": \"Geological layers from the Geological Survey of Sweden: soils, bedrock, wells, groundwater and more. Choose a layer and fetch the features with geometry; limit by an area (bbox).\",\n      \"notes\": \"The layers are read from the service when the source is opened (GetCapabilities or the service directory). Answers are GeoJSON in WGS 84 and open as maps.\"\n    },\n    \"da\": {\n      \"name\": \"SGU åbne geodata (WFS)\",\n      \"description\": \"Geologiske lag fra SGU: jordarter, grundfjeld, brønde, grundvand og mere. Vælg et lag og hent objekterne med geometri; begræns gerne med et område (bbox).\",\n      \"notes\": \"Lagene hentes fra tjenesten, når kilden åbnes (GetCapabilities henholdsvis tjenestekataloget). Svarene er GeoJSON i WGS 84 og åbnes som kort.\"\n    },\n    \"nb\": {\n      \"name\": \"SGU åpne geodata (WFS)\",\n      \"description\": \"Geologiske lag fra SGU: løsmasser, berggrunn, brønner, grunnvann og mer. Velg et lag og hent objektene med geometri; begrens gjerne med et område (bbox).\",\n      \"notes\": \"Lagene hentes fra tjenesten når kilden åpnes (GetCapabilities respektive tjenestekatalogen). Svarene er GeoJSON i WGS 84 og åpnes som kart.\"\n    },\n    \"fi\": {\n      \"name\": \"SGU:n avoin paikkatieto (WFS)\",\n      \"description\": \"Geologisia tasoja SGU:lta: maaperä, kallioperä, kaivot, pohjavesi ja muuta. Valitse taso ja nouda kohteet geometrioineen; rajaa mielellään alueella (bbox).\",\n      \"notes\": \"Tasot noudetaan palvelusta, kun lähde avataan (GetCapabilities tai palveluhakemisto). Vastaukset ovat GeoJSONia WGS 84:ssä ja avautuvat karttoina.\"\n    },\n    \"is\": {\n      \"name\": \"Opin landupplýsingagögn SGU (WFS)\",\n      \"description\": \"Jarðfræðilög frá SGU: jarðgrunnur, berggrunnur, borholur, grunnvatn og fleira. Veldu lag og sæktu fitjurnar með rúmfræði; takmarkaðu gjarnan við svæði (bbox).\",\n      \"notes\": \"Lögin eru sótt úr þjónustunni þegar uppsprettan er opnuð (GetCapabilities eða þjónustuskráin). Svörin eru GeoJSON í WGS 84 og opnast sem kort.\"\n    }\n  }\n}\n");
